const fs = require('fs');
const STATE = '/home/node/.n8n/vdd_longform_pushed.json';
let done = {};
try { done = JSON.parse(fs.readFileSync(STATE, 'utf8')); } catch (e) {}

const body = $input.first().json;
const vids = Array.isArray(body) ? body : (body.videos || []);
const KOFI = 'https://ko-fi.com/versiculodedios';
const today = new Date().toISOString().slice(0,10);

for (const v of vids) {
  const key = v.youtube_id;
  if (!key || done[key]) continue;
  if (v.publish_date && v.publish_date > today) continue;
  const url = v.youtube_url || ('https://youtu.be/' + key);
  const ps = v.push_strategy || {};
  const fb_copy = ps.fb_post_copy || (`\uD83D\uDE4F Nueva publicación en YouTube: ${v.title || ''} \uD83D\uDC49 ${url}\n\n\u2615 Apóyanos: ${KOFI}\n#VersiculoDeDios #PalabraDeDios`);
  const pinned = ps.comentario_pinned || '\uD83D\uDE4F ¿Cuál versículo te tocó más? Déjalo en los comentarios \uD83D\uDC47';
  return [{ json: { key, youtube_id: key, youtube_url: url, fb_copy, pinned } }];
}
return [];

// Refresh YT OAuth token (same pattern as yt-comments-agent)
const http = this.helpers.httpRequest.bind(this);
const body = [
  'client_id=' + encodeURIComponent($env.YOUTUBE_CLIENT_ID),
  'client_secret=' + encodeURIComponent($env.YOUTUBE_CLIENT_SECRET),
  'refresh_token=' + encodeURIComponent($env.YOUTUBE_REFRESH_TOKEN),
  'grant_type=refresh_token'
].join('&');
const t = await http({ method: 'POST', url: 'https://oauth2.googleapis.com/token', headers: { 'Content-Type': 'application/x-www-form-urlencoded' }, body });
if (!t.access_token) throw new Error('YT token refresh failed: ' + JSON.stringify(t));
return [{ json: { fresh_token: t.access_token, youtube_id: $('Pick Next Longform').first().json.youtube_id, pinned: $('Pick Next Longform').first().json.pinned } }];

const fs = require('fs');
const STATE = '/home/node/.n8n/vdd_longform_pushed.json';
const key = $('Pick Next Longform').first().json.youtube_id;
let done = {};
try { done = JSON.parse(fs.readFileSync(STATE, 'utf8')); } catch (e) {}
let fb=null, yt=null;
try { fb = $('FB Post').first().json.id; } catch(e){}
try { const c = $('YT Top Comment').first().json; yt = c.id || (c.error ? null : null); } catch(e){}
done[key] = { pushed_at: new Date().toISOString(), fb_post: fb, yt_comment: yt };
fs.writeFileSync(STATE, JSON.stringify(done, null, 2));
const rec = { ts: new Date().toISOString(), workflow: 'vdd-longform-push', video: key, fb_post: fb, yt_comment: yt };
try { fs.appendFileSync('/var/www/stats/actions.jsonl', JSON.stringify(rec)+'\n'); } catch(e){}
return [{ json: rec }];
